before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
"bufio"
"strings"
)


func main() {
    scanner := bufio.NewScanner(strings.NewReader("abc\n"))
    scanner.Buffer(make([]byte, 0, 4), 8)
    count := 0
    for scanner.Scan() { count++ }
    if err := scanner.Err(); err != nil { fmt.Println("scan failed"); return }
    fmt.Println(count)
}
```

